export type PublicChromeCopy = (typeof publicChromeCopy)["en"];

export function getPublicChromeCopy(locale: Locale): PublicChromeCopy {
  return (publicChromeCopy[locale] ?? publicChromeCopy.en) as PublicChromeCopy;
}
